for group,spell,description in [(6001,10001,'Маленький шарик из смеси двух веществ.'),(6002,10003,'Оба предмета требуются вместе.'),(6003,10004,'Капля святой воды.')]:
    add('ГруппыМатериалов',ID=group,ЗаклинаниеID=spell,Порядок=1,Выбор='все',Описание=description)
