add('МатериалыЗаклинаний',ГруппаID=6001,Порядок=2,ПредметID=5002,ТребованиеТекст='Сера в составе того же шарика с гуано',СпособРасходаID=2)
add('МатериалыЗаклинаний',ГруппаID=6002,Порядок=1,ПредметID=5003,ТребованиеТекст='Жемчужина с минимальной ценностью 100 зм',Количество=1,ЕдиницаID=1,МинимумПредметаММ=10000,СпособРасходаID=2)
add('МатериалыЗаклинаний',ГруппаID=6002,Порядок=2,ПредметID=5004,ТребованиеТекст='Одно совиное перо',Количество=1,ЕдиницаID=1,СпособРасходаID=2)
add('МатериалыЗаклинаний',ГруппаID=6003,Порядок=1,ПредметID=5005,ТребованиеТекст='Одна капля святой воды',Количество=1,ЕдиницаID=3,СпособРасходаID=2)

path=root/'database'/'spells'/'demo-records.json'
path.write_text(json.dumps(dict(version='1.0',reviewed='2026-10-15',descriptionStyle='own_word_summaries',rows=rows),ensure_ascii=False,indent=2)+'\n',encoding='utf-8')
print(json.dumps({'rows':len(rows),'spells':4,'path':str(path)},ensure_ascii=True))
